RECORDS, CHOICES = [], []
_al = lambda s: [x.strip() for x in s.split(",") if x.strip()]


def F(id, icon, name, alias, before, after, src, cond="", after_cond="", note="", status="ok", ask=""):
    RECORDS.append(dict(id=id, icon=icon, name=name, alias=_al(alias), before=before, after=after, src=src.split(), cond=cond, after_cond=after_cond, note=note, status=status, ask=ask))


def O(id, icon, name, alias, ops, src, cond="", status="ok", ask="", kind="opinions"):
    """kind "opinions": poskim disagree. kind "cases": one ruling per way of making or eating it."""
    RECORDS.append(dict(id=id, icon=icon, name=name, alias=_al(alias), ops=[dict(who=o[0], before=o[1], after=o[2], text=o[3] if len(o) > 3 else "") for o in ops], src=src.split(), cond=cond, status=status, ask=ask, kind=kind))


def edit(id, **kw):
    r = next(x for x in RECORDS if x["id"] == id)
    for k, v in kw.items():
        r[k] = _al(v) if k == "alias" else v.split() if k == "src" else v


def Q(id, icon, name, alias="", note="", ask=""):
    RECORDS.append(dict(id=id, icon=icon, name=name, alias=_al(alias), note=note, status="review", ask=ask or "לא נמצא מקור. מה הברכה הראשונה והאחרונה?"))


def C(term, ids, alias="", q="איך אוכלים את זה?"):
    CHOICES.append(dict(term=term, alias=_al(alias), ids=ids.split(), q=q))


