# ---------- candidates from the review brief, each looked up in a per-food source ----------
def kv(slug):
    """a page of the Zer Zahav table (rulings of Rav Ovadia Yosef), read from its HTML"""
    k = "KV:" + slug
    SOURCES[k] = ["לוח מכון זר זהב: " + slug.replace("-", " "), "https://karvenu.co.il/מה-מברכים/" + slug + "/"]
    return k


def mv(path, label):
    """a page of mevarhim.co.il, which restates Peninei Halakha; read through a summarising fetch, so records that rest on it alone are marked review"""
    k = "MV:" + path.strip("/")
    SOURCES[k] = ["מברכים, " + label + " (על פי פניני הלכה)", "https://mevarhim.co.il/" + path]
    return k


def drop(id):
    RECORDS[:] = [r for r in RECORDS if r["id"] != id]


