def S(key, label, url):
    SOURCES[key] = [label, url]
    return key


def redo(maker, id, *a, **kw):
    """replace a record in place, keeping its position on the shelves"""
    i = next(k for k, r in enumerate(RECORDS) if r["id"] == id)
    old = RECORDS.pop(i)
    maker(id, *a, **kw)
    RECORDS.insert(i, RECORDS.pop())
    return old


